int best = Integer.MAX_VALUE;
void enumerate(int u, int target, int cost, boolean[] visited, List<int[]>[] adj) {
    if (u == target) { best = Math.min(best, cost); return; }
    visited[u] = true;
    for (int[] e : adj[u]) {
        if (!visited[e[0]]) enumerate(e[0], target, cost + e[1], visited, adj);
    }
    visited[u] = false;
}

