best = float('inf')

def enumerate_paths(u, target, cost, visited, adj):
    global best
    if u == target:
        best = min(best, cost)
        return
    visited.add(u)
    for v, w in adj[u]:
        if v not in visited:
            enumerate_paths(v, target, cost + w, visited, adj)
    visited.remove(u)

