public int[] bellmanFord(int n, int[][] edges, int src) {
    long[] dist = new long[n];
    Arrays.fill(dist, Long.MAX_VALUE);
    dist[src] = 0;

    for (int pass = 0; pass < n - 1; pass++) {
        boolean changed = false;
        for (int[] e : edges) {
            int u = e[0], v = e[1], w = e[2];
            if (dist[u] != Long.MAX_VALUE && dist[u] + w < dist[v]) {
                dist[v] = dist[u] + w;
                changed = true;
            }
        }
        if (!changed) break;          // converged early
    }

    // Vth pass: any relaxation ⇒ reachable negative cycle
    for (int[] e : edges) {
        int u = e[0], v = e[1], w = e[2];
        if (dist[u] != Long.MAX_VALUE && dist[u] + w < dist[v]) {
            return new int[]{};       // negative cycle
        }
    }

    int[] result = new int[n];
    for (int i = 0; i < n; i++) {
        result[i] = dist[i] == Long.MAX_VALUE ? -1 : (int) dist[i];
    }
    return result;
}

