def bellman_ford(self, n: int, edges: list[list[int]], src: int) -> list[int]:
    INF = float('inf')
    dist = [INF] * n
    dist[src] = 0

    for _ in range(n - 1):
        changed = False
        for u, v, w in edges:
            if dist[u] != INF and dist[u] + w < dist[v]:
                dist[v] = dist[u] + w
                changed = True
        if not changed:
            break                      # converged early

    # Vth pass: any relaxation ⇒ reachable negative cycle
    for u, v, w in edges:
        if dist[u] != INF and dist[u] + w < dist[v]:
            return []                   # negative cycle

    return [-1 if d == INF else d for d in dist]

